    text = path.read_text(encoding='utf-8').replace('"Nuvio Library"','"Omnia Library"').replace('name = "Nuvio"','name = "Omnia"').replace('Client=\\"Nuvio\\"','Client=\\"Omnia\\"')
    path.write_text(text, encoding='utf-8')
